begin;
create table trade_business.documents(company_id uuid not null,id uuid not null,order_id uuid not null,type text not null check(type in ('PI','PO','CI','PL','SC')),purchase_id uuid,shipment_id uuid,state text not null default 'draft' check(state in ('draft','confirmed','void')),version integer not null default 1 check(version>0),terms jsonb,correction_of uuid,created_by uuid not null,created_at timestamptz not null default now(),primary key(company_id,id),unique(company_id,order_id,id),foreign key(company_id,order_id,correction_of) references trade_business.documents(company_id,order_id,id),foreign key(company_id,order_id) references trade_business.orders(company_id,id),foreign key(company_id,order_id,purchase_id) references trade_business.purchase_orders(company_id,order_id,id),foreign key(company_id,order_id,shipment_id) references trade_business.shipments(company_id,order_id,id),check((type='PO' and purchase_id is not null and shipment_id is null) or (type in ('CI','PL') and shipment_id is not null and purchase_id is null) or (type in ('PI','SC') and purchase_id is null and shipment_id is null)));
create table trade_business.document_versions(company_id uuid not null,id uuid not null,document_id uuid not null,version integer not null check(version>0),no text not null,official boolean not null,snapshot jsonb not null,template_version text not null default 'shared-v1',phase text not null default 'pending' check(phase in ('pending','rendering','stored','needs_reconciliation')),file_id uuid,signature_usage_id uuid,created_at timestamptz not null default now(),primary key(company_id,id),unique(company_id,document_id,version),unique(company_id,no),foreign key(company_id,document_id) references trade_business.documents(company_id,id),foreign key(company_id,file_id) references trade_business.file_assets(company_id,id));
create table trade_business.document_jobs(company_id uuid not null,version_id uuid not null,claim_id uuid,claim_until timestamptz,primary key(company_id,version_id),foreign key(company_id,version_id) references trade_business.document_versions(company_id,id));
create table trade_business.order_document_locks(company_id uuid not null,order_id uuid not null,document_id uuid not null,active boolean not null default true,primary key(company_id,document_id),foreign key(company_id,order_id) references trade_business.orders(company_id,id),foreign key(company_id,document_id) references trade_business.documents(company_id,id));
create table trade_business.purchase_document_locks(company_id uuid not null,purchase_id uuid not null,document_id uuid not null,active boolean not null default true,primary key(company_id,document_id),foreign key(company_id,purchase_id) references trade_business.purchase_orders(company_id,id),foreign key(company_id,document_id) references trade_business.documents(company_id,id));
create table trade_business.shipment_document_locks(company_id uuid not null,shipment_id uuid not null,document_id uuid not null,active boolean not null default true,primary key(company_id,document_id),foreign key(company_id,shipment_id) references trade_business.shipments(company_id,id),foreign key(company_id,document_id) references trade_business.documents(company_id,id));
grant select,insert on trade_business.documents,trade_business.document_versions,trade_business.document_jobs,trade_business.order_document_locks,trade_business.purchase_document_locks,trade_business.shipment_document_locks to business_backend;
grant update(state,version) on trade_business.documents to business_backend;
grant update(phase,file_id) on trade_business.document_versions to business_backend;
grant update(claim_id,claim_until) on trade_business.document_jobs to business_backend;
grant update(active) on trade_business.order_document_locks,trade_business.purchase_document_locks,trade_business.shipment_document_locks to business_backend;
commit;
